function j(data,status=200,headers={}){const h=new Headers(headers);h.set("content-type","application/json; charset=utf-8");h.set("cache-control","no-store");return new Response(JSON.stringify(data),{status,headers:h})}
function page(body,headers={}){const h=new Headers(headers);h.set("content-type","text/html; charset=utf-8");h.set("cache-control","no-store");return new Response(body,{status:200,headers:h})}
function clean(v,n=500){return String(v==null?"":v).trim().slice(0,n)}
function canWrite(auth){return auth?.user?.role==="owner"}
function validProductImage(value){
 if(!value)return true;if(value.length>300000)return false;
 if(/^https:\/\//i.test(value)){try{const u=new URL(value);return u.protocol==='https:'&&!/[\s<>"']/.test(value)}catch{return false}}
 const m=value.match(/^data:image\/(webp|png|jpeg);base64,([A-Za-z0-9+/]+={0,2})$/i);if(!m||m[2].length%4)return false;
 try{const h=atob(m[2].slice(0,32));return m[1].toLowerCase()==='webp'?h.startsWith('RIFF')&&h.slice(8,12)==='WEBP':m[1].toLowerCase()==='png'?h.startsWith('\x89PNG\r\n\x1a\n'):h.startsWith('\xff\xd8\xff')}catch{return false}
}
function productPriceError(b){for(const keys of [['price'],['listPrice','list_price'],['salePrice','sale_price']])for(const key of keys){if(!Object.prototype.hasOwnProperty.call(b,key)||b[key]===null||b[key]==='')continue;if(typeof b[key]==='boolean'||!Number.isFinite(Number(b[key]))||Number(b[key])<0)return 'INVALID_PRODUCT_PRICE';}return '';}
function adminProductImage(product){const current=String(product.image_url||'');return current&&validProductImage(current)?current:''}

