function featuredValue(value){if(value===true||value===1||value==='1')return 1;if(value===false||value===0||value==='0')return 0;throw new Error('INVALID_FEATURED_VALUE')}
async function upsertProductMeta(env,productId,b,statements=null){
 const fields=[
  {column:'brand_id',keys:['brandId','brand_id'],convert:v=>clean(v,120)||null,fallback:null},
  {column:'description',keys:['description'],convert:v=>clean(v,5000),fallback:''},
  {column:'seo_title',keys:['seoTitle','seo_title'],convert:v=>clean(v,220),fallback:''},
  {column:'seo_description',keys:['seoDescription','seo_description'],convert:v=>clean(v,500),fallback:''},
  {column:'sort_order',keys:['sortOrder','sort_order'],convert:v=>Number(v)||0,fallback:0},
  {column:'featured',keys:['featured'],convert:featuredValue,fallback:0}
 ];
 const values=[productId],updates=[];
 for(const field of fields){const key=field.keys.find(key=>Object.prototype.hasOwnProperty.call(b,key));values.push(key?field.convert(b[key]):field.fallback);if(key)updates.push(field.column+'=excluded.'+field.column)}
 updates.push("updated_at=datetime('now')");
 const statement=env.DB.prepare("INSERT INTO oky_product_meta_v1(product_id,brand_id,description,seo_title,seo_description,sort_order,featured,updated_at) VALUES(?,?,?,?,?,?,?,datetime('now')) ON CONFLICT(product_id) DO UPDATE SET "+updates.join(',')).bind(...values);
 if(statements){statements.push(statement);return;}
 const result=await statement.run();
 if(result?.success===false)throw new Error('PRODUCT_META_SAVE_FAILED');
}

async function upsertProductCommerce(env,productId,b,statements=null){
 const old=await env.DB.prepare("SELECT * FROM oky_product_commerce_v1 WHERE product_id=?").bind(productId).first();
 const has=k=>Object.prototype.hasOwnProperty.call(b,k);
 const txt=(k,db,n=500)=>clean(has(k)?b[k]:(old?.[db]??""),n);
 const num=(k,db,def=null)=>has(k)?(b[k]===""||b[k]==null?null:Number(b[k])):(old?.[db]??def);
 const flag=(k,db)=>has(k)?(b[k]?1:0):Number(old?.[db]||0);
 const sku=txt("sku","sku",120),barcode=txt("barcode","barcode",120),subcategory=txt("subcategory","subcategory",180),origin=txt("origin","origin",180),storage=txt("storageConditions","storage_conditions",1000);
 const cold=flag("coldChain","cold_chain"),minOrder=Math.max(0.001,Number(num("minOrderQty","min_order_qty",1)||1)),step=Math.max(0.001,Number(num("qtyStep","qty_step",1)||1));
 const listPrice=num("listPrice","list_price",null),salePrice=num("salePrice","sale_price",null),newUntil=txt("newUntil","new_until",80)||null,best=flag("bestSeller","best_seller");
 if(listPrice!=null&&(!Number.isFinite(listPrice)||listPrice<0))throw new Error("INVALID_LIST_PRICE");
 if(salePrice!=null&&(!Number.isFinite(salePrice)||salePrice<0))throw new Error("INVALID_SALE_PRICE");
 const statement=env.DB.prepare(`INSERT INTO oky_product_commerce_v1(product_id,sku,barcode,subcategory,origin,storage_conditions,cold_chain,min_order_qty,qty_step,list_price,sale_price,new_until,best_seller,updated_at)
 VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,datetime('now'))
 ON CONFLICT(product_id) DO UPDATE SET sku=excluded.sku,barcode=excluded.barcode,subcategory=excluded.subcategory,origin=excluded.origin,storage_conditions=excluded.storage_conditions,cold_chain=excluded.cold_chain,min_order_qty=excluded.min_order_qty,qty_step=excluded.qty_step,list_price=excluded.list_price,sale_price=excluded.sale_price,new_until=excluded.new_until,best_seller=excluded.best_seller,updated_at=datetime('now')`)
 .bind(productId,sku||null,barcode||null,subcategory||null,origin||null,storage||null,cold,minOrder,step,listPrice,salePrice,newUntil,best);
 if(statements){statements.push(statement);return;}
 await statement.run();
}

async function saveProductBatch(env,statements){
 if(typeof env.DB?.batch!=='function')throw new Error('PRODUCT_ATOMIC_SAVE_UNAVAILABLE');
 const results=await env.DB.batch(statements);
 if(results?.some(result=>result?.success===false))throw new Error('PRODUCT_ATOMIC_SAVE_FAILED');
}

